Headline identification: a paragraph whose text contains at least one letter and whose
cased characters are all uppercase (e.g., "EXECUTIVE SUMMARY", "Q1 2025 OUTLOOK").
Body paragraphs, bullet items, and the table header use sentence case, so they are
excluded. For each matched paragraph, add <w:u w:val="single"/> to every run's <w:rPr>.
"""
import os
import sys
import xml.etree.ElementTree as ET

W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
ET.register_namespace("w", W_NS)

def q(tag):
    return "{%s}%s" % (W_NS, tag)

def para_text(p):
    return "".join(t.text or "" for t in p.iter(q("t")))

def is_headline(text):
    has_alpha = any(ch.isalpha() for ch in text)
    if not has_alpha:
        return False
    # All alphabetic characters must be uppercase; digits/punct are ignored
    return all((not ch.isalpha()) or ch.isupper() for ch in text)

def main():
    path = os.path.join("unpacked", "word", "document.xml")
    if not os.path.exists(path):
        print("ERROR: %s not found; cwd=%s" % (path, os.getcwd()))
        sys.exit(1)
    tree = ET.parse(path)
    root = tree.getroot()
    body = root.find(q("body"))
    if body is None:
        print("ERROR: no w:body found")
        sys.exit(1)

    underlined = []
    for p in body.findall(q("p")):
        text = para_text(p)
        if not is_headline(text):
            continue
        changed = False
        for r in p.findall(q("r")):
            rpr = r.find(q("rPr"))
            if rpr is None:
                rpr = ET.SubElement(r, q("rPr"))
                r.remove(rpr)
                r.insert(0, rpr)
            if rpr.find(q("u")) is None:
                # rPr here only contains rFonts/sz/szCs, all of which precede w:u in schema order
                ET.SubElement(rpr, q("u")).set("val", "single")
                changed = True
        if changed:
            underlined.append(text)

    tree.write(path, encoding="ascii", xml_declaration=True)
    print("Underlined %d headline paragraph(s):" % len(underlined))
    for t in underlined:
        print("  - %s" % t)

