#!/usr/bin/env python3
"""Underline every headline in quarterly_report.docx (unpacked OOXML).

Headlines are the all-caps section heading paragraphs of the report. For each
such paragraph, every text-bearing run is given a schema-valid underline run
property: <w:u w:val="single"/> (existing invalid <w:u val="single"/> entries
are replaced, since an unqualified "val" attribute is ignored by Word).
Body paragraphs and all other content are left untouched.
"""
import io
import re
import sys
from xml.dom import minidom

W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
XML_PATH = sys.argv[1] if len(sys.argv) > 1 else "quarterly_unpacked/word/document.xml"


def element_children(node, name):
    return [c for c in node.childNodes
            if c.nodeType == c.ELEMENT_NODE and c.tagName == name]


def text_content(p):
    out = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild is not None:
            out.append("".join(ch.data for ch in t.childNodes
                                if ch.nodeType == ch.TEXT_NODE))
    return "".join(out)


def is_headline(text):
    """All-caps section heading text (no lowercase, no bullet/table/box chars)."""
    if not text:
        return False
    if re.search(r"[a-z]", text):
        return False
    # bullets, box-drawing/table rows, arrows, dashes, accented chars, symbols
    if re.search(r"[\u2022\u2500-\u257f\u2190-\u21ff\u2013\u2014\u2018-\u201d\u00c0-\u024f]", text):
        return False
    return bool(re.search(r"[A-Z]", text))


def make_u(doc):
    u = doc.createElementNS(W_NS, "w:u")
    u.setAttributeNS(W_NS, "w:val", "single")
    return u


def run_has_text(r):
    for t in r.getElementsByTagName("w:t"):
        if t.firstChild is not None and any(
                ch.nodeType == ch.TEXT_NODE and ch.data.strip()
                for ch in t.childNodes):
            return True
    return False


def main():
    doc = minidom.parse(XML_PATH)
    body = doc.getElementsByTagName("w:body")[0]
    paras = element_children(body, "w:p")
    headlines = [p for p in paras if is_headline(text_content(p))]

    underlined = []
    for p in headlines:
        for r in p.getElementsByTagName("w:r"):
            if not run_has_text(r):
                continue
            rpr = None
            for c in element_children(r, "w:rPr"):
                rpr = c
                break
            if rpr is None:
                rpr = doc.createElementNS(W_NS, "w:rPr")
                r.insertBefore(rpr, r.firstChild)
            # Replace any existing (possibly invalid) <w:u> entry.
            for u in [c for c in rpr.childNodes
                      if c.nodeType == c.ELEMENT_NODE and c.tagName == "w:u"]:
                rpr.removeChild(u)
            rpr.appendChild(make_u(doc))
            if p not in underlined:
                underlined.append(p)

    # Serialize compactly, preserving the original ascii XML declaration and
    # re-encoding any non-ASCII character data back to numeric character refs.
    sio = io.StringIO()
    doc.writexml(sio, newl="")
    s = sio.getvalue()
    start = s.find("<w:document")
    assert start != -1, "document root not found"
    out = '<?xml version="1.0" encoding="ascii"?>\n' + s[start:]
    out = "".join(ch if ord(ch) < 128 else "&#%d;" % ord(ch) for ch in out)

    with open(XML_PATH, "w", encoding="ascii") as fh:
        fh.write(out)

    # Self-check: reparse to ensure the result is well formed.
    minidom.parse(XML_PATH)
    print("Headlines underlined: %d" % len(underlined))
    for p in underlined:
        print("  - %s" % text_content(p))


if __name__ == "__main__":
    main()

